package tron

import (
	"encoding/base64"
	"encoding/json"
	"testing"

	"github.com/golang/snappy"
)

func TestDecodeMsg(t *testing.T) {
	// 
	data := ""
	decodeBytes, _ := base64.StdEncoding.DecodeString(data)
	output, _ := snappy.Decode(nil, decodeBytes)
	// os.WriteFile("test.log", output, 0644)
	//{"type":"evm-incremental","chain":"tron","data":{"block_number":78899874,"tron_block":{"blockID":"0000000004b3eaa26f2c7ff95302b80a02e9fcca1aeac4c2965c5f0b0824f271","block_header":{"raw_data":{"number":78899874,"txTrieRoot":"aa553203fdc3d02c63888fbb9d1d80eac635c75ecefdbe73e651fd9c8e535b5d","witness_address":"4162398d516b555ac64af24416e05c199c01823048","parentHash":"0000000004b3eaa1b27e0d7371d8283dd70a484513ef92de849bb96e99257d8c","version":32,"timestamp":1767362571000},"witness_signature":"d8f3c3a496d80e3e40875e878a73cb3caaeadb550500faee2e910f46951b10c565c851c80f2b8ff9e81a240c40d7900e7a82e27acdb6f5ba86c7272c6027588901"},"transactions":[]},"tron_tx_infos":[],"tvm_block":{},"tvm_receipts":[]},"timestamp":0,"block_number":78899874,"delay_flag":true}
	var msg TronMsg
	err := json.Unmarshal(output, &msg)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("timestamp ms: %d", msg.Data.TronBlock.BlockHeader.RawData.Timestamp)
}
